// Control-panel key: toggles a status LED for the technician.
// Key on D2 (pull-up to Vcc, closes to ground), LED on D13.

const int KEY_PIN = 2;
const int LED_PIN = 13;
const unsigned long REPORT_MS = 1000;
const unsigned long SETTLE_MS = 40;

bool ledLit = false;
int stableLevel = HIGH;
int lastRaw = HIGH;
unsigned long rawChangedMs = 0;
unsigned long lastReport = 0;
unsigned long edgeCount = 0;
unsigned long bootMs = 0;

void writeLed(bool on)
{
    ledLit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void flipLed()
{
    writeLed(!ledLit);
    edgeCount++;
}

void report()
{
    Serial.print("panel led=");
    Serial.print(ledLit ? 1 : 0);
    Serial.print(" edges=");
    Serial.println(edgeCount);
}

void setup()
{
    pinMode(KEY_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    writeLed(false);
    Serial.begin(9600);
    lastRaw = digitalRead(KEY_PIN);
    stableLevel = lastRaw;
    rawChangedMs = millis();
    lastReport = millis();
    bootMs = millis();
}

void loop()
{
    int nowLevel = digitalRead(KEY_PIN);
    unsigned long t = millis();

    if (nowLevel != lastRaw)
    {
        lastRaw = nowLevel;
        rawChangedMs = t;
    }

    if (lastRaw != stableLevel && (t - rawChangedMs) >= SETTLE_MS)
    {
        int newLevel = lastRaw;
        if (stableLevel == HIGH && newLevel == LOW)
        {
            flipLed();
        }
        stableLevel = newLevel;
    }

    if (t - lastReport >= REPORT_MS)
    {
        lastReport = t;
        report();
    }
}
